        private void LoadFragments()
        {
            try
            {
                foreach (string data in EmbeddedFragments())
                {
                    fragments.Add(FileStorage.server.Store(
                        Convert.FromBase64String(data),
                        FileStorage.Type.png,
                        CommunityEntity.ServerInstance.net.ID));
                }
                Puts("Battle Rust intro animation ready: " + fragments.Count + " fragments.");
            }
            catch (Exception ex)
            {
                if (CommunityEntity.ServerInstance != null)
                {
                    foreach (uint id in fragments)
                        FileStorage.server.Remove(id, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);
                }
                fragments.Clear();
                PrintWarning("Intro animation unavailable; using complete logo: " + ex.Message);
            }
        }

        private CuiRectTransformComponent FragmentPosition(int index, float elapsed)
        {
            const int columns = 4;
            const int rows = 3;
            int col = index % columns;
            int row = index / columns;

            float t = Mathf.Clamp01((elapsed - index * FragmentStagger) / AssembleSeconds);
            float q = t - 1f;
            float ease = 1f + 2.2f * q * q * q + 1.2f * q * q;
            float remaining = 1f - ease;

            float angle = (index * 137.5f + 25f) * Mathf.Deg2Rad;
            float dx = Mathf.Cos(angle) * (150f + (index % 3) * 30f);
            float dy = Mathf.Sin(angle) * (135f + (index % 4) * 25f);
            float w = IntroLogoWidth / columns;
            float h = IntroLogoHeight / rows;
            float scale = 1f + 0.40f * remaining;
            float cx = (col + 0.5f) * w + dx * remaining;
            float cy = (rows - 1 - row + 0.5f) * h + dy * remaining;

            return new CuiRectTransformComponent
            {
                AnchorMin = "0 0",
                AnchorMax = "0 0",
                Pivot = "0.5 0.5",
                OffsetMin = XY(cx - w * scale * 0.5f, cy - h * scale * 0.5f),
                OffsetMax = XY(cx + w * scale * 0.5f, cy + h * scale * 0.5f),
                Rotation = ((index % 2 == 0 ? 1f : -1f) * (28f + index * 4f)) * remaining
            };
        }

        private void AddIntroCompleteLogo(CuiElementContainer ui, string parent)
        {
            if (welcomeLogoId == 0) return;

            ui.Add(new CuiElement
            {
                Name = IntroRoot + ".Logo",
                Parent = parent,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = welcomeLogoId.ToString(),
                        Color = "1 1 1 1",
                        BlocksRaycast = false
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0", AnchorMax = "0 0",
                        OffsetMin = "0 0", OffsetMax = XY(IntroLogoWidth, IntroLogoHeight)
                    }
                }
            });
        }

        private void AddFlyingIntroLogo(CuiElementContainer ui, string parent)
        {
            if (welcomeLogoId == 0) return;

            ui.Add(new CuiElement
            {
                Name = IntroRoot + ".Preload",
                Parent = parent,
                Components =
                {
                    new CuiRawImageComponent
                    {
                        Png = welcomeLogoId.ToString(), Color = "1 1 1 0", BlocksRaycast = false
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = "0 0", AnchorMax = "0 0",
                        OffsetMin = "0 0", OffsetMax = XY(IntroLogoWidth, IntroLogoHeight)
                    }
                }
            });

            for (int i = 0; i < fragments.Count; i++)
            {
                ui.Add(new CuiElement
                {
                    Name = IntroRoot + ".Fragment." + i,
                    Parent = parent,
                    Components =
                    {
                        new CuiRawImageComponent
                        {
                            Png = fragments[i].ToString(),
                            Color = "1 1 1 0.98",
                            FadeIn = 0.22f,
                            BlocksRaycast = false
                        },
                        FragmentPosition(i, 0f)
                    }
                });
            }
        }

        private void Animate()
        {
            if (flights.Count == 0) return;

            foreach (ulong id in new List<ulong>(flights.Keys))
            {
                Flight flight = flights[id];
                BasePlayer player = flight.Player;
                if (player == null || !player.IsConnected)
                {
                    flights.Remove(id);
                    continue;
                }

                float elapsed = Time.realtimeSinceStartup - flight.Started - ImageWarmup;
                if (elapsed < 0f) continue;

                if (elapsed >= AssembleSeconds + (fragments.Count - 1) * FragmentStagger)
                {
                    for (int i = 0; i < fragments.Count; i++)
                        CuiHelper.DestroyUi(player, IntroRoot + ".Fragment." + i);

                    CuiHelper.DestroyUi(player, IntroRoot + ".Preload");
                    CuiElementContainer finalUi = new CuiElementContainer();
                    AddIntroCompleteLogo(finalUi, flight.Parent);
                    CuiHelper.AddUi(player, finalUi);
                    flights.Remove(id);
                    continue;
                }

                CuiElementContainer update = new CuiElementContainer();
                for (int i = 0; i < fragments.Count; i++)
                {
                    update.Add(new CuiElement
                    {
                        Name = IntroRoot + ".Fragment." + i,
                        Parent = flight.Parent,
                        Update = true,
                        Components = { FragmentPosition(i, elapsed) }
                    });
                }
                CuiHelper.AddUi(player, update);
            }
        }

