        private class StatRecord
        {
            public string Name = "Unknown";
            public int Kills;
            public int Deaths;
        }

        protected override void LoadDefaultConfig()
        {
            config = new PluginConfig();
            config.ConfigRevision = 400;
            SaveConfig();
        }

        protected override void LoadConfig()
        {
            base.LoadConfig();
            try
            {
                config = Config.ReadObject<PluginConfig>();
                if (config == null) throw new Exception("Config is empty");
                EnsureConfig();
                SaveConfig();
            }
            catch (Exception ex)
            {
                PrintWarning("Invalid config, creating a new one: " + ex.Message);
                LoadDefaultConfig();
            }
        }

        protected override void SaveConfig()
        {
            Config.WriteObject(config, true);
        }

        private void EnsureConfig()
        {
            if (config.Links == null) config.Links = new List<LinkEntry>();
            if (config.Rules == null) config.Rules = new List<string>();
            if (config.UI == null) config.UI = new UiConfig();
            if (config.WelcomeLines == null) config.WelcomeLines = new PluginConfig().WelcomeLines;
            if (config.InfoLines == null) config.InfoLines = new PluginConfig().InfoLines;
            if (string.IsNullOrEmpty(config.TimeZoneLabel)) config.TimeZoneLabel = "UTC+3";

            // Migration from the old all-in-one version (ELO / bonuses removed):
            // put the new description in once, after that it is fully yours to edit.
            if (config.ConfigRevision < 400)
            {
                PluginConfig defaults = new PluginConfig();
                config.ServerDescription = defaults.ServerDescription;
                config.WelcomeLines = defaults.WelcomeLines;
                config.ConfigRevision = 400;
            }
        }

        #endregion

        #region Hooks / Commands

        private void Init()
        {
            LoadStats();
        }

        private void OnServerInitialized()
        {
            statsSaveTimer = timer.Every(300f, SaveStats);
            try
            {
                byte[] image = EmbeddedLogo();
                logoId = FileStorage.server.Store(image, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);

                byte[] welcomeImage = EmbeddedWelcomeLogo();
                welcomeLogoId = FileStorage.server.Store(welcomeImage, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);

                Puts("Embedded BattleRust menu and welcome logos loaded.");
                LoadFragments();
            }
            catch (Exception ex)
            {
                PrintWarning("Could not load embedded logo: " + ex.Message);
            }

            timer.Every(1f, CheckPending);
            timer.Every(0.05f, Animate);
            timer.Every(15f, RefreshDynamicMainPages);

            timer.Once(1f, () =>
            {
                foreach (BasePlayer player in BasePlayer.activePlayerList)
                {
                    if (!openTabs.ContainsKey(player.userID))
                        ShowMenuLogo(player);
                }
            });
        }

        private void OnServerSave()
        {
            SaveStats();
        }

        private void OnNewSave(string filename)
        {
            if (!config.ResetStatsOnWipe) return;
            stats = new StatsStore();
            statsDirty = true;
            SaveStats();
            Puts("Detected a new save: K/D statistics were reset.");
        }

        private void OnPlayerConnected(BasePlayer player)
        {
            if (player == null) return;
            if (config.ShowOnJoin)
                pending.Add(player.userID);
        }

        private void OnPlayerSleepEnded(BasePlayer player)
        {
            TryShow(player);

            if (player != null && !pending.Contains(player.userID) && !welcomeOpen.Contains(player.userID) && !openTabs.ContainsKey(player.userID))
                ShowMenuLogo(player);
        }

        private void OnPlayerDisconnected(BasePlayer player, string reason)
        {
            Close(player, false);
        }

        private void OnPlayerDeath(BasePlayer player, HitInfo info)
        {
            if (player == null) return;

            // Only real players (Steam IDs) are counted; scientists and other NPCs are ignored.
            if (player.userID.IsSteamId())
            {
                GetStat(player.userID, player.displayName).Deaths++;

                BasePlayer killer = info != null ? info.InitiatorPlayer : null;
                if (killer != null && killer != player && killer.userID.IsSteamId())
                    GetStat(killer.userID, killer.displayName).Kills++;

                statsDirty = true;
                Close(player, false);
            }
        }

        private void Unload()
        {
            SaveStats();
            statsSaveTimer?.Destroy();

            foreach (BasePlayer player in BasePlayer.activePlayerList)
                Close(player, false);

            pending.Clear();
            welcomeOpen.Clear();
            openTabs.Clear();
            flights.Clear();

            if (CommunityEntity.ServerInstance != null)
            {
                foreach (uint id in fragments)
                    FileStorage.server.Remove(id, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);
            }
            fragments.Clear();

            if (logoId != 0 && CommunityEntity.ServerInstance != null)
            {
                FileStorage.server.Remove(logoId, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);
                logoId = 0;
            }

            if (welcomeLogoId != 0 && CommunityEntity.ServerInstance != null)
            {
                FileStorage.server.Remove(welcomeLogoId, FileStorage.Type.png, CommunityEntity.ServerInstance.net.ID);
                welcomeLogoId = 0;
            }
        }

