        [ConsoleCommand("battlerustwelcome.close")]
        private void CloseCommand(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player != null) Close(player, true);
        }

        [ConsoleCommand("battlerustwelcome.open")]
        private void OpenFromLogoCommand(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player != null) Open(player, "main");
        }

        [ConsoleCommand("battlerustwelcome.tab")]
        private void TabCommand(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null || !arg.HasArgs(1)) return;

            string tab = arg.GetString(0).ToLowerInvariant();
            if (tab != "main" && tab != "info" && tab != "stats" && tab != "rules") return;
            Open(player, tab);
        }

        [ConsoleCommand("battlerustwelcome.link")]
        private void LinkCommand(ConsoleSystem.Arg arg)
        {
            BasePlayer player = arg.Player();
            if (player == null || !arg.HasArgs(1)) return;

            int index;
            if (!int.TryParse(arg.GetString(0), out index)) return;
            if (index < 0 || index >= config.Links.Count) return;

            LinkEntry link = config.Links[index];
            SendReply(player, "<color=#C8DF95>" + EscapeRich(link.Name) + ":</color> " + link.Url);
        }

        [HookMethod("API_OpenTab")]
        private object API_OpenTab(BasePlayer player, string tab)
        {
            if (player == null || !player.IsConnected) return false;
            string normalized = string.IsNullOrEmpty(tab) ? "main" : tab.ToLowerInvariant();
            if (normalized != "main" && normalized != "info" && normalized != "stats" && normalized != "rules") normalized = "main";
            Open(player, normalized);
            return true;
        }

        private void CheckPending()
        {
            if (pending.Count == 0) return;

            foreach (ulong id in new List<ulong>(pending))
            {
                BasePlayer player = BasePlayer.FindByID(id);
                if (player == null || !player.IsConnected)
                {
                    pending.Remove(id);
                    continue;
                }

                TryShow(player);
            }
        }

        private void TryShow(BasePlayer player)
        {
            if (player == null || !pending.Contains(player.userID) || !player.IsConnected ||
                player.IsReceivingSnapshot || player.IsSleeping() || player.IsDead())
                return;

            pending.Remove(player.userID);
            ShowWelcomeIntro(player);
        }

        private void RefreshDynamicMainPages()
        {
            if (openTabs.Count == 0) return;

            foreach (KeyValuePair<ulong, string> pair in new Dictionary<ulong, string>(openTabs))
            {
                if (pair.Value != "main") continue;

                BasePlayer player = BasePlayer.FindByID(pair.Key);
                if (player == null || !player.IsConnected)
                {
                    openTabs.Remove(pair.Key);
                    continue;
                }

                DrawContent(player, pair.Value);
            }
        }

        #endregion

        #region Stats

        private void LoadStats()
        {
            try
            {
                stats = Interface.Oxide.DataFileSystem.ReadObject<StatsStore>(StatsFile);
            }
            catch (Exception ex)
            {
                PrintWarning("Could not read stats file, starting empty: " + ex.Message);
            }

            if (stats == null) stats = new StatsStore();
            if (stats.Players == null) stats.Players = new Dictionary<ulong, StatRecord>();
        }

        private void SaveStats()
        {
            if (stats == null || !statsDirty) return;
            try
            {
                Interface.Oxide.DataFileSystem.WriteObject(StatsFile, stats);
                statsDirty = false;
            }
            catch (Exception ex)
            {
                PrintError("Stats save failed: " + ex.Message);
            }
        }

        private StatRecord GetStat(ulong id, string name)
        {
            StatRecord rec;
            if (!stats.Players.TryGetValue(id, out rec))
            {
                rec = new StatRecord();
                stats.Players[id] = rec;
            }
            if (!string.IsNullOrEmpty(name)) rec.Name = name;
            return rec;
        }

        #endregion

        #region UI Core

        private void Open(BasePlayer player, string tab)
        {
            if (player == null || !player.IsConnected || player.IsReceivingSnapshot || player.IsSleeping() || player.IsDead())
                return;

            pending.Remove(player.userID);
            Close(player, false);
            openTabs[player.userID] = tab;

            CuiElementContainer ui = new CuiElementContainer();

            ui.Add(new CuiPanel
            {
                Image = { Color = config.UI.Backdrop, FadeIn = UiFade },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" },
                CursorEnabled = true,
                KeyboardEnabled = false
            }, "Overlay", Root);

            AddRounded(ui, Root, Root + ".Glow",
                "0.5 0.5", "0.5 0.5", "-467 -347", "467 347",
