        private void ShowWelcomeIntro(BasePlayer player)
        {
            if (player == null || !player.IsConnected || player.IsReceivingSnapshot || player.IsSleeping() || player.IsDead())
                return;

            pending.Remove(player.userID);
            Close(player, false);
            welcomeOpen.Add(player.userID);
            HideMenuLogo(player);

            CuiElementContainer ui = new CuiElementContainer();

            // Welcome is a separate screen: no server menu is drawn here.
            ui.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0.06", FadeIn = 0.20f },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" },
                CursorEnabled = true,
                KeyboardEnabled = false
            }, "Overlay", Root);

            string stage = ui.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0", BlocksRaycast = false },
                RectTransform =
                {
                    AnchorMin = "0.5 0.5", AnchorMax = "0.5 0.5",
                    OffsetMin = XY(-IntroLogoWidth / 2f, -IntroLogoHeight / 2f),
                    OffsetMax = XY(IntroLogoWidth / 2f, IntroLogoHeight / 2f)
                }
            }, Root, IntroRoot + ".Stage");

            if (welcomeLogoId != 0)
            {
                if (fragments.Count == 12)
                    AddFlyingIntroLogo(ui, stage);
                else
                    AddIntroCompleteLogo(ui, stage);
            }

            AddText(ui, Root, "ДОБРО ПОЖАЛОВАТЬ НА", 24, config.UI.Text,
                TextAnchor.MiddleCenter, "0.5 0.5", "0.5 0.5", "-330 176", "330 220", true);

            // Server info lines under the logo (e.g. "Это наш MEDIUM сервер", "Рейты x2 • Стаки x2").
            int lineCount = Math.Min(config.WelcomeLines.Count, 3);
            for (int i = 0; i < lineCount; i++)
            {
                AddText(ui, Root, EscapeRich(config.WelcomeLines[i]), i == 0 ? 24 : 20,
                    i == 0 ? config.UI.Text : config.UI.Accent,
                    TextAnchor.MiddleCenter, "0.5 0.5", "0.5 0.5",
                    XY(-360f, -220f - i * 44f), XY(360f, -176f - i * 44f), true);
            }

            ui.Add(new CuiButton
            {
                Button =
                {
                    Color = "0.08 0.085 0.075 0.42",
                    Command = "battlerustwelcome.close",
                    FadeIn = 0.20f
                },
                Text =
                {
                    Text = "×",
                    FontSize = 28,
                    Align = TextAnchor.MiddleCenter,
                    Color = config.UI.Text
                },
                RectTransform =
                {
                    AnchorMin = "1 1", AnchorMax = "1 1",
                    OffsetMin = "-72 -72", OffsetMax = "-24 -24"
                }
            }, Root, IntroRoot + ".Close");

            if (!CuiHelper.AddUi(player, ui))
                return;

            if (welcomeLogoId != 0 && fragments.Count == 12)
            {
                flights[player.userID] = new Flight
                {
                    Player = player,
                    Parent = IntroRoot + ".Stage",
                    Started = Time.realtimeSinceStartup
                };
            }
        }

        private void DrawContent(BasePlayer player, string tab)
        {
            if (player == null || !player.IsConnected) return;

            CuiHelper.DestroyUi(player, Content + ".Page");

            CuiElementContainer ui = new CuiElementContainer();
            ui.Add(new CuiPanel
            {
                Image = { Color = "0 0 0 0" },
                RectTransform = { AnchorMin = "0 0", AnchorMax = "1 1" }
            }, Content, Content + ".Page");

            if (tab == "rules")
                DrawRulesPage(ui, Content + ".Page");
            else if (tab == "info")
                DrawInfoPage(ui, Content + ".Page");
            else if (tab == "stats")
                DrawStatsPage(ui, Content + ".Page", player);
            else
                DrawMainPage(ui, Content + ".Page");

            CuiHelper.AddUi(player, ui);
        }

        private void DrawMainPage(CuiElementContainer ui, string parent)
        {
            // Server info card.
            AddRounded(ui, parent, parent + ".InfoCard",
                "0 1", "1 1", "0 -190", "0 0",
                config.UI.GlassLight, "", UiFade, "0.86 0.90 0.72 0.14", "1 1");

            AddText(ui, parent + ".InfoCard", "О СЕРВЕРЕ", 14, config.UI.Accent,
                TextAnchor.UpperLeft, "0 0", "1 1", "26 22", "-26 -24", true);
            AddText(ui, parent + ".InfoCard", config.ServerName, 28, config.UI.Text,
                TextAnchor.UpperLeft, "0 0", "1 1", "26 54", "-26 -56", true);
            AddText(ui, parent + ".InfoCard", config.ServerDescription, 16, config.UI.TextMuted,
                TextAnchor.UpperLeft, "0 0", "1 1", "26 18", "-26 -96", false);

            // Stats cards.
            float cardGap = 10f;
            float cardWidth = 201f;
            AddStatCard(ui, parent, "ONLINE", GetOnlineText(),
                "Игроков сейчас на сервере", 0f, -206f, cardWidth, 145f);
            AddStatCard(ui, parent, "ПОСЛЕДНИЙ ВАЙП", GetLastWipeText(),
                "Дата создания текущей карты", cardWidth + cardGap, -206f, cardWidth, 145f);
            AddStatCard(ui, parent, "СЛЕДУЮЩИЙ ВАЙП", GetNextWipeText(),
                "Расчёт по настройкам сервера", (cardWidth + cardGap) * 2f, -206f, cardWidth, 145f);

            AddText(ui, parent, "ССЫЛКИ", 14, config.UI.Accent,
                TextAnchor.MiddleLeft, "0 0", "1 0", "4 118", "0 146", true);

            int shown = Math.Min(config.Links.Count, 2);
            float available = 623f;
            float gap = 12f;
            float width = shown > 0 ? (available - gap * (shown - 1)) / shown : available;
            for (int i = 0; i < shown; i++)
            {
                AddLinkButton(ui, parent, config.Links[i], i, i * (width + gap), 20f, width, 88f);
            }

            if (shown == 0)
            {
                AddText(ui, parent, "Добавь ссылки в конфиге плагина.", 15, config.UI.TextMuted,
                    TextAnchor.MiddleLeft, "0 0", "1 0", "4 34", "0 92", false);
            }
        }

        private void DrawInfoPage(CuiElementContainer ui, string parent)
        {
            string card = parent + ".InfoTab";
            AddRounded(ui, parent, card,
                "0 0", "1 1", "0 0", "0 0",
                config.UI.GlassLight, "", UiFade, "0.86 0.90 0.72 0.14", "1 1");

            AddText(ui, card, "О СЕРВЕРЕ", 15, config.UI.Accent,
                TextAnchor.UpperLeft, "0 0", "1 1", "28 24", "-28 -22", true);
            AddText(ui, card, config.ServerName, 28, config.UI.Text,
                TextAnchor.UpperLeft, "0 0", "1 1", "28 24", "-28 -52", true);

            StringBuilder sb = new StringBuilder();
            int count = Math.Min(config.InfoLines.Count, 12);
            for (int i = 0; i < count; i++)
            {
                if (i > 0) sb.Append("\n\n");
                sb.Append("<color=#C8DF95>•</color>  ").Append(EscapeRich(config.InfoLines[i]));
            }

            if (count == 0)
                sb.Append("Информация пока не заполнена. Добавь строки в InfoLines в конфиге плагина.");

            AddText(ui, card, sb.ToString(), 18, config.UI.Text,
                TextAnchor.UpperLeft, "0 0", "1 1", "28 24", "-28 -108", false);
        }

        private void DrawStatsPage(CuiElementContainer ui, string parent, BasePlayer player)
        {
            StatRecord rec = GetStat(player.userID, player.displayName);
            float kd = rec.Deaths > 0 ? (float)rec.Kills / rec.Deaths : rec.Kills;

            float gap = 10f;
            float width = 201f;
            AddStatCard(ui, parent, "K / D", kd.ToString("0.00", CultureInfo.InvariantCulture),
                "Убийства на одну смерть", 0f, 0f, width, 145f);
            AddStatCard(ui, parent, "УБИЙСТВА", rec.Kills.ToString(CultureInfo.InvariantCulture),
                "Убито игроков", width + gap, 0f, width, 145f);
            AddStatCard(ui, parent, "СМЕРТИ", rec.Deaths.ToString(CultureInfo.InvariantCulture),
                "Сколько раз ты погиб", (width + gap) * 2f, 0f, width, 145f);

            AddText(ui, parent,
                config.ResetStatsOnWipe ? "Статистика сбрасывается после вайпа." : "Статистика сохраняется между вайпами.",
                14, config.UI.TextMuted, TextAnchor.UpperLeft, "0 1", "1 1", "4 -190", "0 -160", false);
        }

