        private void AddRounded(CuiElementContainer ui, string parent, string name,
            string anchorMin, string anchorMax, string offsetMin, string offsetMax,
            string color, string material, float fade, string outlineColor, string outlineDistance)
        {
            CuiElement element = new CuiElement
            {
                Name = name,
                Parent = parent,
                Components =
                {
                    new CuiImageComponent
                    {
                        Color = color,
                        Sprite = RoundedSprite,
                        ImageType = UnityEngine.UI.Image.Type.Sliced,
                        Material = string.IsNullOrEmpty(material) ? null : material,
                        FadeIn = fade
                    },
                    new CuiRectTransformComponent
                    {
                        AnchorMin = anchorMin,
                        AnchorMax = anchorMax,
                        OffsetMin = offsetMin,
                        OffsetMax = offsetMax
                    }
                }
            };

            if (!string.IsNullOrEmpty(outlineColor) && outlineColor != "0 0 0 0")
            {
                element.Components.Add(new CuiOutlineComponent
                {
                    Color = outlineColor,
                    Distance = outlineDistance
                });
            }

            ui.Add(element);
        }

