        #region Data Helpers

        private string GetOnlineText()
        {
            int online = BasePlayer.activePlayerList.Count;
            int max = ConVar.Server.maxplayers;
            return online + " / " + max;
        }

        private static readonly DateTime WipeScheduleAnchorMsk = new DateTime(2026, 9, 17, 17, 0, 0, DateTimeKind.Unspecified);
        private const int WipeScheduleIntervalDays = 2;

        private DateTime GetLastWipe()
        {
            DateTime now = DateTime.UtcNow.AddHours(3d);
            if (now < WipeScheduleAnchorMsk)
                return WipeScheduleAnchorMsk.AddDays(-WipeScheduleIntervalDays);

            double cycles = Math.Floor((now - WipeScheduleAnchorMsk).TotalDays / WipeScheduleIntervalDays);
            return WipeScheduleAnchorMsk.AddDays(cycles * WipeScheduleIntervalDays);
        }

        private DateTime GetNextWipe()
        {
            DateTime now = DateTime.UtcNow.AddHours(3d);
            if (now < WipeScheduleAnchorMsk)
                return WipeScheduleAnchorMsk;

            double cycles = Math.Floor((now - WipeScheduleAnchorMsk).TotalDays / WipeScheduleIntervalDays) + 1d;
            return WipeScheduleAnchorMsk.AddDays(cycles * WipeScheduleIntervalDays);
        }

        private string GetLastWipeText()
        {
            return GetLastWipe().ToString("dd.MM.yyyy HH:mm") + " " + config.TimeZoneLabel;
        }

        private string GetNextWipeText()
        {
            DateTime next = GetNextWipe();
            TimeSpan left = next - DateTime.UtcNow.AddHours(3d);
            string date = next.ToString("dd.MM.yyyy HH:mm") + " " + config.TimeZoneLabel;

            if (left.TotalSeconds <= 0)
                return date;

            if (left.TotalDays >= 1)
                return date + "\n<size=12><color=#B9C7B9>через " + ((int)Math.Floor(left.TotalDays)) + " дн. " + left.Hours + " ч.</color></size>";

            return date + "\n<size=12><color=#B9C7B9>через " + Math.Max(0, left.Hours) + " ч. " + Math.Max(0, left.Minutes) + " мин.</color></size>";
        }

        private void Close(BasePlayer player, bool showMenuLogo = true)
        {
            if (player == null) return;

            pending.Remove(player.userID);
            welcomeOpen.Remove(player.userID);
            openTabs.Remove(player.userID);
            flights.Remove(player.userID);
            CuiHelper.DestroyUi(player, Root);

            if (showMenuLogo)
                ShowMenuLogo(player);
            else
                HideMenuLogo(player);
        }

        private static string XY(float x, float y)
        {
            return x.ToString("0.###", CultureInfo.InvariantCulture) + " " +
                   y.ToString("0.###", CultureInfo.InvariantCulture);
        }

        private static string SafePlayerName(string value)
        {
            return EscapeRich(string.IsNullOrEmpty(value) ? "игрок" : value);
        }

        private static string EscapeRich(string value)
        {
            if (string.IsNullOrEmpty(value)) return string.Empty;
            return value.Replace("<", "‹").Replace(">", "›");
        }

        #endregion
    }
}
